s=s.replace('{services.map(s=><article','{catalog.map(s=><article')
s=s.replace('<span><strong>{s.title}</strong><b>','<span><strong>{s.title}</strong><small className="proposal-builder__selected-label">{selected.includes(s.id)?\'✓ Incluído na seleção\':\'Adicionar à proposta\'}</small><b>')
