s=s.replace('</aside></div></div>','''</aside></div><div className="proposal-builder__mobile-summary"><div><span>Operação mensal</span><strong>{money(monthly+budget)}</strong><small>Implantação: {money(initial)} à parte</small></div><a href="#selection-title">Ver resumo ↑</a></div></div>''')
